# Regenera as listas em Markdown a partir de ERP-CRM/dados/. A fonte da verdade sao os arquivos de dados.
# Uso: powershell -NoProfile -ExecutionPolicy Bypass -File ferramentas/gerar-visoes.ps1
param([string]$Raiz = (Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)))
$ErrorActionPreference = 'Stop'
$u = [Text.Encoding]::UTF8; $w8 = New-Object Text.UTF8Encoding($false); $DirErp = Join-Path $Raiz 'ERP-CRM'
function Jl([string]$n) { $f = Join-Path (Join-Path $DirErp 'dados') $n; if (-not (Test-Path -LiteralPath $f)) { return @() }; return @([IO.File]::ReadAllLines($f, $u) | Where-Object { $_.Trim() } | ForEach-Object { $_ | ConvertFrom-Json }) }
function Grava([string]$rel, [string]$t) { $f = Join-Path $Raiz $rel; $p = Split-Path $f -Parent; if (-not (Test-Path -LiteralPath $p)) { [void](New-Item -ItemType Directory -Force -Path $p) }; [IO.File]::WriteAllText($f, $t.Replace("`r`n", "`n"), $w8) }
function Fm([string]$id, [string]$tit) { return "---`nid: $id`ntitulo: $tit`ntipo: GUIA-PARA-IA`nversao: V02`ncriado_em: 2026-11-04`ncriado_por: Claude (a pedido de Diego [PES-00001])`nbase: IMG-CAD-006 V10`n---`n`n" }
function Cods($l) { $cr = [char]96; return ((@($l) | ForEach-Object { "$cr$_$cr" }) -join ', ') }
function Vz($x) { return ($null -eq $x -or "$x" -eq '') }

$itens = Jl 'itens.jsonl'; $decs = Jl 'decisoes.jsonl'; $fluxos = Jl 'fluxos.jsonl'; $ents = Jl 'entidades.jsonl'; $perf = Jl 'perfis.jsonl'
$TIPOS = [ordered]@{ 'FLX-MACRO' = 'Fluxo macro'; 'FLX-MICRO' = 'Etapas do fluxo'; 'FLX-DECISAO' = 'Pontos de decisão'; 'FLX-NOTIF' = 'Notificações'; 'ESC-MODULO' = 'Módulos e telas'; 'ESC-PERFIL' = 'Perfis e responsáveis'; 'ESC-DOC' = 'Documentos gerados'; 'ESC-DADOS' = 'Entidades e campos'; 'ESC-INTEG' = 'Integrações'; 'ESC-INDIC' = 'Dashboards e indicadores'; 'TEC' = 'Requisitos técnicos'; 'REG-PRAZO' = 'Prazos'; 'REG-APROV' = 'Aprovações e alçadas'; 'REG-PRECO' = 'Preço, margem e comissão'; 'REG-ACESSO' = 'Acesso e visibilidade'; 'REG-CODIGO' = 'Códigos e rastreabilidade'; 'REG-QUAL' = 'Qualidade'; 'REG-LEGAL' = 'Legal e fiscal'; 'REG-CALC' = 'Cálculos e critérios'; 'REG-OPER' = 'Regras operacionais'; 'PEND' = 'Pendências'; 'IDEIA' = 'Ideias sem compromisso' }
$MODS = [ordered]@{ CRM = 'CRM e prospecção'; PLC = 'Planejamento comercial'; DIS = 'Distribuição de clientes'; REU = 'Reuniões com IA'; PRJ = 'Projetos e memorial'; BIB = 'Biblioteca de itens e locações'; APR = 'Apresentações por IA'; CUS = 'Custos'; COM = 'Comercial, proposta e contrato'; FIN = 'Financeiro'; CMP = 'Compras'; PLA = 'Planejamento de produção'; CRD = 'Credenciamento'; PRD = 'Produção e app dos setores'; CVI = 'Comunicação visual'; AUD = 'Audiovisual'; GRA = 'Criação gráfica'; DCO = 'Decoração'; D3F = 'Impressão 3D'; TIN = 'Tecnologia e experiências interativas'; ALM = 'Almoxarifado'; EXP = 'Expedição e qualidade'; LOG = 'Logística e frota'; MON = 'Montagem'; POS = 'Pós-feira'; MKT = 'Marketing e acervo'; CLI = 'Portal do cliente'; FID = 'Indicação e fidelidade'; INC = 'Incentivo e desempenho'; EVT = 'Produção de evento'; TRP = 'Transversal' }
$VIG = [ordered]@{ 'decisao-diego' = 'Diego decidiu. Vale o campo `decisao`, e não o texto, que descreve o conflito antigo.'; 'confirmado' = 'O texto segue uma decisão de Diego.'; 'vigente' = 'O documento registra como decidido, sem decisão contrária conhecida.'; 'proposto' = 'Proposta sem aprovação registrada. Use como requisito provisório.'; 'inferido' = 'Deduzido no documento. Confirme antes de fechar.'; 'a-conferir' = 'Pode estar desatualizado por uma decisão. Veja o campo `atencao`.'; 'pendencia-parcial' = 'Pendência respondida em parte por uma decisão.'; 'pendente' = 'Em aberto. Pergunte.'; 'adiado' = 'Diego adiou. Não decida.'; 'substituido-parcial' = 'Uma decisão muda parte do item. **Use** o que está em `continua` e siga a decisão no que está em `mudou`.'; 'substituido' = 'Não use. Vale a decisão indicada.'; 'desatualizado' = 'Superado por fonte mais nova. Não use.'; 'fato' = 'Fato ou dado de algo já feito, e não requisito.' }
$NU = 'substituido', 'desatualizado'
$porDec = @{}; foreach ($d in $decs) { $porDec[$d.id] = $d }
function NomeArq([string]$s) { return (([Text.Encoding]::ASCII.GetString([Text.Encoding]::GetEncoding('ISO-8859-8').GetBytes($s))) -replace '[ ,]+', '-').ToUpper() }

function LinhaDec($d) { $x = "- **$($d.id)** ($($d.assunto)): $($d.decisao)"; if (-not (Vz $d.em_aberto)) { $x += " **Em aberto:** $($d.em_aberto)" }; if ($d.situacao -notlike 'Decidido por*') { $x += " _($($d.situacao))_" }; if (-not (Vz $d.registro)) { $x += " Registro: ``$($d.registro)``" }; return $x }
function LinhaItem($o, [bool]$comMod) {
  $tags = @($o.tipo); if ($comMod) { $tags += $o.modulo }; $tags += $o.vigencia; if ($o.confianca -ne 'alta') { $tags += "conf:$($o.confianca)" }; if (-not (Vz $o.contexto)) { $tags += $o.contexto }
  $fonte = "$($o.doc)"; if (-not (Vz $o.localizacao)) { $fonte += " · $($o.localizacao)" }; if (-not (Vz $o.item_original)) { $fonte += " · $($o.item_original)" }; if (-not (Vz $o.pai)) { $fonte += " · parte de $($o.pai)" }
  $x = "- ``$($o.id)`` " + (($tags | ForEach-Object { "``$_``" }) -join ' ') + " $($o.texto) _[$fonte]_"
  if (-not (Vz $o.continua)) { $x += "`n  - **Continua valendo:** $($o.continua)" }
  if (-not (Vz $o.mudou)) { $x += "`n  - **Mudou:** $($o.mudou)" }
  if (-not (Vz $o.decisao) -and $o.vigencia -ne 'substituido-parcial') { $x += "`n  - **Decisão ($($o.decisao_situacao)):** $($o.decisao)"; if (-not (Vz $o.em_aberto)) { $x += " **Em aberto:** $($o.em_aberto)" }; if (-not (Vz $o.registro)) { $x += " Registro: ``$($o.registro)``" } }
  if (-not (Vz $o.atencao) -and $o.vigencia -in 'a-conferir', 'pendencia-parcial') { $x += "`n  - **Atenção (leitura do Claude):** $($o.atencao)" }
  if (-not (Vz $o.filhos)) { $x += "`n  - Requisitos separados deste item: $(Cods ($o.filhos -split ', '))" }
  if (-not (Vz $o.origem_fora)) { $x += "`n  - Origem fora do repositório: $($o.origem_fora)" }
  return $x
}

# ---------- MODULOS
$arqMod = @{}; $porModD = @{}; foreach ($d in $decs) { if (-not $porModD[$d.modulo]) { $porModD[$d.modulo] = @() }; $porModD[$d.modulo] += $d }
foreach ($m in $MODS.Keys) {
  $ids = @($itens | Where-Object { $_.modulo -eq $m }); $rel = "ERP-CRM/MODULOS/$m-$(NomeArq $MODS[$m]).md"; $arqMod[$m] = $rel
  $sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm "ERP-MOD-$m" "Módulo $($MODS[$m])")); [void]$sb.AppendLine("# $m · $($MODS[$m])"); [void]$sb.AppendLine(); [void]$sb.AppendLine("$($ids.Count) itens de desenvolvimento. Como ler as etiquetas: ``ERP-CRM/TAXONOMIA.md``. A ordem das etapas está em ``ERP-CRM/FLUXOS/``."); [void]$sb.AppendLine()
  if ($porModD[$m]) { [void]$sb.AppendLine('## Decisões de Diego'); [void]$sb.AppendLine(); foreach ($d in $porModD[$m]) { [void]$sb.AppendLine((LinhaDec $d)) }; [void]$sb.AppendLine() }
  foreach ($t in $TIPOS.Keys) { $sel = @($ids | Where-Object { $_.tipo -eq $t -and $NU -notcontains $_.vigencia }); if ($sel.Count) { [void]$sb.AppendLine("## $($TIPOS[$t]) ($($sel.Count))"); [void]$sb.AppendLine(); foreach ($i in $sel) { [void]$sb.AppendLine((LinhaItem $i $false)) }; [void]$sb.AppendLine() } }
  $n2 = @($ids | Where-Object { $NU -contains $_.vigencia }); if ($n2.Count) { [void]$sb.AppendLine("## Não usar: substituídos ou desatualizados ($($n2.Count))"); [void]$sb.AppendLine(); foreach ($i in $n2) { [void]$sb.AppendLine((LinhaItem $i $false)) }; [void]$sb.AppendLine() }
  Grava $rel $sb.ToString()
}

# ---------- listas por tipo
function Visao([string]$rel, [string]$id, [string]$tit, [string]$intro, [string[]]$lista) {
  $sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm $id $tit)); [void]$sb.AppendLine("# $tit"); [void]$sb.AppendLine(); [void]$sb.AppendLine($intro); [void]$sb.AppendLine()
  foreach ($cod in $lista) { $sel = @($itens | Where-Object { $_.tipo -eq $cod -and $NU -notcontains $_.vigencia }); if (-not $sel.Count) { continue }
    [void]$sb.AppendLine("## $($TIPOS[$cod]) ($($sel.Count))"); [void]$sb.AppendLine()
    foreach ($m in $MODS.Keys) { $s2 = @($sel | Where-Object { $_.modulo -eq $m }); if ($s2.Count) { [void]$sb.AppendLine("### $m · $($MODS[$m]) ($($s2.Count))"); [void]$sb.AppendLine(); foreach ($i in $s2) { [void]$sb.AppendLine((LinhaItem $i $false)) }; [void]$sb.AppendLine() } } }
  Grava $rel $sb.ToString()
}
Visao 'ERP-CRM/02A_ITENS-DE-FLUXO.md' 'ERP-ITENS-FLUXO' 'Itens de fluxo por tipo' 'Lista de consulta. Para construir, use `ERP-CRM/FLUXOS/`, que traz as etapas em ordem.' @('FLX-MACRO', 'FLX-MICRO', 'FLX-DECISAO', 'FLX-NOTIF')
Visao 'ERP-CRM/03_ESCOPO-FUNCIONAL.md' 'ERP-ESCOPO' 'Escopo funcional' 'Lista de consulta: módulos, telas, perfis, documentos, entidades, integrações, indicadores e requisitos técnicos. Ideias ficam ao final e não são compromisso.' @('ESC-MODULO', 'ESC-PERFIL', 'ESC-DOC', 'ESC-DADOS', 'ESC-INTEG', 'ESC-INDIC', 'TEC', 'IDEIA')
Visao 'ERP-CRM/04_REGRAS-DE-NEGOCIO.md' 'ERP-REGRAS' 'Regras de negócio' 'Lista de consulta: prazos, aprovações, preço, acesso, códigos, qualidade, legal, cálculos e regras operacionais. As decisões de Diego prevalecem.' @('REG-PRAZO', 'REG-APROV', 'REG-PRECO', 'REG-ACESSO', 'REG-CODIGO', 'REG-QUAL', 'REG-LEGAL', 'REG-CALC', 'REG-OPER')

# ---------- pendencias por impacto
$TRAVA = [ordered]@{ 'dados' = 'Trava o modelo de dados'; 'fluxo' = 'Trava um fluxo ou uma transição'; 'acesso' = 'Trava perfis e permissões'; 'integracao' = 'Trava uma integração'; 'config' = 'Pode seguir: deixe como parâmetro configurável'; 'conteudo' = 'Pode seguir: depende de conteúdo ou texto'; 'sem-trava' = 'Não trava o desenvolvimento'; '' = 'Ainda sem análise de impacto' }
$pen = @($itens | Where-Object { ($_.tipo -eq 'PEND' -or $_.vigencia -in 'pendente', 'pendencia-parcial', 'adiado') -and $NU -notcontains $_.vigencia -and -not ($_.vigencia -eq 'decisao-diego' -and (Vz $_.em_aberto)) })
$sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm 'ERP-PENDENCIAS' 'Pendências a decidir')); [void]$sb.AppendLine('# Pendências a decidir'); [void]$sb.AppendLine(); [void]$sb.AppendLine("$($pen.Count) perguntas em aberto, da que mais trava para a que menos trava. Nos itens `decisao-diego`, vale a decisão, e só a parte **Em aberto** continua pendente. A análise de impacto é leitura do Claude. Não decida por conta própria: registre a dúvida em ``ERP-CRM/ANDAMENTO/DUVIDAS.md``, para Diego ou o Pedro responder. Quando a pendência for de parâmetro, construa o campo configurável e siga."); [void]$sb.AppendLine()
foreach ($k in $TRAVA.Keys) { $s1 = @($pen | Where-Object { "$($_.trava)" -eq $k }); if (-not $s1.Count) { continue }; [void]$sb.AppendLine("## $($TRAVA[$k]) ($($s1.Count))"); [void]$sb.AppendLine(); foreach ($i in ($s1 | Sort-Object modulo, id)) { [void]$sb.AppendLine((LinhaItem $i $true)) }; [void]$sb.AppendLine() }
Grava 'ERP-CRM/05_PENDENCIAS-A-DECIDIR.md' $sb.ToString()

# ---------- substituidos
$sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm 'ERP-SUBSTITUIDOS' 'Substituídos: não usar')); $s6 = @($itens | Where-Object { $NU -contains $_.vigencia }); $sp = @($itens | Where-Object { $_.vigencia -eq 'substituido-parcial' })
[void]$sb.AppendLine('# Substituídos: não usar'); [void]$sb.AppendLine(); [void]$sb.AppendLine("Estes $($s6.Count) itens ficaram para trás por inteiro. Se um documento de origem disser o que está aqui, vale a decisão indicada. Quais itens contrariam uma decisão é leitura do Claude, marcada a pedido de Diego."); [void]$sb.AppendLine(); [void]$sb.AppendLine("Outros $($sp.Count) itens têm a etiqueta ``substituido-parcial``: parte deles continua valendo, então ficam nos módulos e nas listas, com **Continua valendo** e **Mudou**."); [void]$sb.AppendLine()
foreach ($i in $s6) { [void]$sb.AppendLine((LinhaItem $i $true)) }; Grava 'ERP-CRM/06_SUBSTITUIDOS-NAO-USAR.md' $sb.ToString()

# ---------- fluxos
$FX = [ordered]@{ PRO = @('01', 'Prospecção'); COM = @('02', 'Comercial'); ENT = @('03', 'Entrada pelo WhatsApp'); PRJ = @('04', 'Projetos'); CUS = @('05', 'Custos'); ACM = @('06', 'Assistente comercial'); FIN = @('07', 'Financeiro'); CMP = @('08', 'Compras'); ALM = @('09', 'Almoxarifado'); FRT = @('10', 'Frota'); PLA = @('11', 'Planejamento'); CRD = @('12', 'Credenciamento'); PRD = @('13', 'Setores produtivos'); CVI = @('14', 'Comunicação visual'); AUD = @('15', 'Audiovisual'); EXP = @('16', 'Expedição e qualidade'); MON = @('17', 'Montagem'); POS = @('18', 'Pós-feira'); MKT = @('19', 'Marketing'); INC = @('20', 'Incentivo') }
$ligados = @{}; foreach ($i in $itens) { if (-not (Vz $i.etapas)) { foreach ($e in ($i.etapas -split ', ')) { if (-not $ligados[$e]) { $ligados[$e] = New-Object Collections.ArrayList }; [void]$ligados[$e].Add($i) } } }
function Mid([string]$s) { return ($s -replace '[^A-Za-z0-9]', '_') }
function Mtx([string]$s) { return ($s -replace '["\[\]{}()|<>#;]', ' ').Trim() }
$idx = New-Object Text.StringBuilder; $resumo = @()
foreach ($c in $FX.Keys) {
  $st = @($fluxos | Where-Object { $_.fluxo -eq $c } | Sort-Object { [int]$_.ordem }); if (-not $st.Count) { continue }
  $rel = "ERP-CRM/FLUXOS/$($FX[$c][0])-$c-$(NomeArq $FX[$c][1]).md"; $sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm "ERP-FLX-$c" "Fluxo $($FX[$c][1])"))
  [void]$sb.AppendLine("# Fluxo $c · $($FX[$c][1])"); [void]$sb.AppendLine(); [void]$sb.AppendLine("$($st.Count) etapas em ordem de execução, com as decisões de Diego aplicadas. Montado por agentes a partir da Especificação e dos documentos de setor, e ainda não revisado por Diego nem pelo Pedro. Como ler: ``ERP-CRM/FLUXOS/00_VISAO-GERAL.md``."); [void]$sb.AppendLine()
  [void]$sb.AppendLine('```mermaid'); [void]$sb.AppendLine('flowchart TD')
  foreach ($s in $st) { $rot = "$($s.etapa): $(Mtx $s.nome)"; if ($s.situacao -eq 'substituida') { $rot += ' (substituída)' }; [void]$sb.AppendLine("  $(Mid $s.etapa)[`"$rot`"]") }
  foreach ($s in $st) { foreach ($p in @($s.proximas)) { if (Vz $p.para) { continue }; $lab = Mtx "$($p.condicao)"; $seta = if ($p.explicita) { '-->' } else { '-.->' }; if ($lab) { [void]$sb.AppendLine("  $(Mid $s.etapa) $seta|`"$lab`"| $(Mid $p.para)") } else { [void]$sb.AppendLine("  $(Mid $s.etapa) $seta $(Mid $p.para)") } } }
  [void]$sb.AppendLine('```'); [void]$sb.AppendLine()
  foreach ($s in $st) {
    [void]$sb.AppendLine("## $($s.ordem). $($s.etapa) · $($s.nome) ``$($s.situacao)``"); [void]$sb.AppendLine()
    [void]$sb.AppendLine("- **O que acontece:** $($s.o_que)"); [void]$sb.AppendLine("- **Responsável:** $($s.responsavel)"); $pp = @($s.perfis | Where-Object { $_ }); if ($pp.Count) { [void]$sb.AppendLine("- **Perfis:** $(Cods $pp)") }; [void]$sb.AppendLine("- **Prazo:** $($s.prazo)"); [void]$sb.AppendLine("- **Gatilho:** $($s.gatilho)")
    $pr = @($s.proximas | Where-Object { $_ -and -not (Vz $_.para) } | ForEach-Object { $t = "``$($_.para)``"; if (-not (Vz $_.condicao)) { $t = "$($_.condicao): $t" }; if (-not $_.explicita) { $t += ' _(pela ordem do documento)_' }; $t }); if ($pr.Count) { [void]$sb.AppendLine("- **Próxima:** $($pr -join '; ')") }
    if (-not (Vz $s.mudanca)) { [void]$sb.AppendLine("- **Mudou em relação ao documento:** $($s.mudanca)") }
    $dd = @($s.decisoes | Where-Object { $_ }); if ($dd.Count) { [void]$sb.AppendLine("- **Decisões aplicadas:** $(Cods $dd)") }
    if (-not (Vz $s.em_aberto)) { [void]$sb.AppendLine("- **Em aberto:** $($s.em_aberto)") }
    $li = @(); if ($ligados[$s.etapa]) { $li = @($ligados[$s.etapa] | ForEach-Object { $mk = if ($NU -contains $_.vigencia) { ' (não usar)' } else { '' }; "``$($_.id)``$mk" }) }; if ($li.Count) { [void]$sb.AppendLine("- **Itens:** $($li -join ', ')") }
    [void]$sb.AppendLine("- **Fonte:** $($s.fonte)"); [void]$sb.AppendLine()
  }
  Grava $rel $sb.ToString(); [void]$idx.AppendLine("| ``$c`` | [$($FX[$c][1])](FLUXOS/$(Split-Path $rel -Leaf)) | $($st.Count) | $(@($st | Where-Object { $_.situacao -eq 'ajustada' }).Count) | $(@($st | Where-Object { $_.situacao -eq 'substituida' }).Count) | $(@($st | Where-Object { $_.situacao -eq 'nova-por-decisao' }).Count) |")
}
$sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm 'ERP-FLUXOS' 'Fluxos do sistema')); [void]$sb.AppendLine('# Fluxos do sistema'); [void]$sb.AppendLine(); [void]$sb.AppendLine('Cada fluxo fica em um arquivo, em ordem de execução, com as decisões de Diego aplicadas. Comece por `ERP-CRM/FLUXOS/00_VISAO-GERAL.md`. A lista de itens por tipo está em `ERP-CRM/02A_ITENS-DE-FLUXO.md`.'); [void]$sb.AppendLine(); [void]$sb.AppendLine('| Código | Fluxo | Etapas | Ajustadas | Substituídas | Novas por decisão |'); [void]$sb.AppendLine('|---|---|---:|---:|---:|---:|'); [void]$sb.Append($idx.ToString()); Grava 'ERP-CRM/02_FLUXOS.md' $sb.ToString()

# ---------- entidades
if ($ents.Count) { $sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm 'ERP-ENTIDADES' 'Entidades e dados')); [void]$sb.AppendLine('# Entidades e dados'); [void]$sb.AppendLine(); [void]$sb.AppendLine("**Proposta provisória do Claude, para a outra IA partir dela, e não modelo final.** Junta a seção 4 da Especificação, os itens ``ESC-DADOS`` e as decisões de Diego. Cada campo cita o item de origem. Tipos de dado, chaves e tabelas ficam para quem constrói. $($ents.Count) entidades."); [void]$sb.AppendLine()
  foreach ($e in $ents) { [void]$sb.AppendLine("## $($e.entidade)"); [void]$sb.AppendLine(); [void]$sb.AppendLine("$($e.descricao)"); [void]$sb.AppendLine(); if (@($e.modulos).Count) { [void]$sb.AppendLine("**Módulos:** $(@($e.modulos) -join ', ')"); [void]$sb.AppendLine() }
    if (@($e.campos).Count) { [void]$sb.AppendLine('| Campo | Detalhe | Origem |'); [void]$sb.AppendLine('|---|---|---|'); foreach ($q in $e.campos) { [void]$sb.AppendLine("| $($q.campo) | $(("$($q.detalhe)") -replace '\|', '/') | $(Cods @($q.uni)) |") }; [void]$sb.AppendLine() }
    if (@($e.status).Count) { [void]$sb.AppendLine("**Status:** $(@($e.status) -join ' · ')"); [void]$sb.AppendLine() }; if (@($e.relacoes).Count) { [void]$sb.AppendLine("**Relações:** $(@($e.relacoes) -join '; ')"); [void]$sb.AppendLine() }
    if (-not (Vz $e.decisoes) -and @($e.decisoes).Count) { [void]$sb.AppendLine("**Decisões aplicadas:** $(@($e.decisoes) -join ', ')"); [void]$sb.AppendLine() }; if (-not (Vz $e.em_aberto)) { [void]$sb.AppendLine("**Em aberto:** $($e.em_aberto)"); [void]$sb.AppendLine() }; if (-not (Vz $e.fonte)) { [void]$sb.AppendLine("**Fonte:** $($e.fonte)"); [void]$sb.AppendLine() } }
  Grava 'ERP-CRM/07_ENTIDADES.md' $sb.ToString() }

# ---------- perfis
if ($perf.Count) { $sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm 'ERP-PERFIS' 'Perfis e permissões')); [void]$sb.AppendLine('# Perfis e permissões'); [void]$sb.AppendLine(); [void]$sb.AppendLine("**Proposta provisória do Claude.** Junta a seção 8 da Especificação, os itens ``ESC-PERFIL`` e ``REG-ACESSO`` e as decisões de Diego. **Construa as permissões por perfil, nunca por nome de pessoa.** Os ocupantes podem mudar, e a lista oficial depende da correção de Diego (item-16). $($perf.Count) perfis."); [void]$sb.AppendLine()
  $usadas = @($perf | ForEach-Object { if ($_.acessos) { $_.acessos.PSObject.Properties.Name } } | Select-Object -Unique); $colunas = @($MODS.Keys | Where-Object { $usadas -contains $_ })
  [void]$sb.AppendLine('## Matriz'); [void]$sb.AppendLine(); [void]$sb.AppendLine('`V` vê, `E` edita, `A` aprova. **Célula vazia significa "o material não informa", e não "sem acesso".** Na dúvida, registre em `ERP-CRM/ANDAMENTO/DUVIDAS.md` e deixe fechado.'); [void]$sb.AppendLine(); [void]$sb.AppendLine("| Perfil | $($colunas -join ' | ') |"); [void]$sb.AppendLine("|---|$(($colunas | ForEach-Object { '---' }) -join '|')|")
  foreach ($p in $perf) { $cel = foreach ($k in $colunas) { $v = ''; if ($p.acessos -and $p.acessos.PSObject.Properties[$k]) { $v = $p.acessos.$k }; $v }; [void]$sb.AppendLine("| ``$($p.codigo)`` | $($cel -join ' | ') |") }; [void]$sb.AppendLine()
