# ---------- taxonomia
$sb = New-Object Text.StringBuilder; [void]$sb.Append((Fm 'ERP-TAXONOMIA' 'Categorias e etiquetas')); [void]$sb.AppendLine('# Categorias e etiquetas'); [void]$sb.AppendLine(); [void]$sb.AppendLine('Organização autorizada por Diego em 04/11/2026: "Autorizado nova organizacao, novas categorias, novas tags, etiquetas, assuntos". As listas são proposta do Claude. Elas valem para o catálogo e esta camada; as categorias de registro da skill `registro-imagine` não mudaram. Este repositório só traz os itens de desenvolvimento (`uso: DES`).'); [void]$sb.AppendLine()
[void]$sb.AppendLine('## `tipo`'); [void]$sb.AppendLine(); [void]$sb.AppendLine('| Código | Significado | Itens |'); [void]$sb.AppendLine('|---|---|---:|'); foreach ($t in $TIPOS.Keys) { [void]$sb.AppendLine("| ``$t`` | $($TIPOS[$t]) | $(@($itens | Where-Object { $_.tipo -eq $t }).Count) |") }; [void]$sb.AppendLine()
[void]$sb.AppendLine('## `modulo`'); [void]$sb.AppendLine(); [void]$sb.AppendLine('| Código | Módulo | Itens | Arquivo |'); [void]$sb.AppendLine('|---|---|---:|---|'); foreach ($m in $MODS.Keys) { [void]$sb.AppendLine("| ``$m`` | $($MODS[$m]) | $(@($itens | Where-Object { $_.modulo -eq $m }).Count) | ``$($arqMod[$m])`` |") }; [void]$sb.AppendLine()
[void]$sb.AppendLine('## `vigencia`: posso usar?'); [void]$sb.AppendLine(); [void]$sb.AppendLine('| Código | O que fazer | Itens |'); [void]$sb.AppendLine('|---|---|---:|'); foreach ($v in $VIG.Keys) { [void]$sb.AppendLine("| ``$v`` | $($VIG[$v]) | $(@($itens | Where-Object { $_.vigencia -eq $v }).Count) |") }; [void]$sb.AppendLine()
[void]$sb.AppendLine('## `situacao` das etapas em `dados/fluxos.jsonl`'); [void]$sb.AppendLine(); [void]$sb.AppendLine('`vigente`: nenhuma decisão muda a etapa. `ajustada`: uma decisão muda parte dela, e o texto já traz a versão correta. `substituida`: a decisão elimina a etapa, e o campo `mudanca` diz o que acontece no lugar. `nova-por-decisao`: só existe por causa de uma decisão, com código `XXX-Dn`. O campo `perfis` traz os códigos de `dados/perfis.jsonl`, mapeados do texto de `responsavel` pelo Claude; `SISTEMA` e `AGENTE-IA` indicam etapa automática.'); [void]$sb.AppendLine()
[void]$sb.AppendLine('## Campos de `dados/itens.jsonl`'); [void]$sb.AppendLine(); [void]$sb.AppendLine('- `continua` e `mudou`: a parte que vale e a que mudou, em `substituido-parcial`.'); [void]$sb.AppendLine('- `pai` e `filhos`: um item como `UNI-00752.03` é um requisito que antes estava dentro do complemento de `UNI-00752`.'); [void]$sb.AppendLine('- `etapas`: códigos das etapas ligadas ao item, que apontam para `ERP-CRM/FLUXOS/`.'); [void]$sb.AppendLine('- `doc_arquivo` e `origem_fora`: onde conferir a origem, ou por que ela ficou fora do repositório.'); [void]$sb.AppendLine('- `contexto`: `rotina-anterior` marca itens que descrevem o trabalho antes do ERP. Use a regra, e não a ferramenta citada, e veja DUV-045.'); [void]$sb.AppendLine('- `trava`: o que a pendência impede: `dados`, `fluxo`, `acesso`, `integracao`, `config`, `conteudo` ou `sem-trava`. Leitura do Claude.'); [void]$sb.AppendLine('- `confianca`: `alta`, `media` ou `baixa`, a certeza da classificação em `tipo` e `modulo`, e não a certeza da regra.'); Grava 'ERP-CRM/TAXONOMIA.md' $sb.ToString()
